package com.bank.citystats;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class MostCommonCityDemo {
    private static final Logger log = Logger.getLogger("CityStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "Mumbai"),
            new Employee("Amit", "Mumbai"),
            new Employee("Priya", "Delhi"),
            new Employee("Neha", "Mumbai"));
        CityStatsService service = new CityStatsService();

        log.info(() -> "Most common city: " + service.mostCommonCity(staff).orElse("none"));
    }
}

