class Employee {
    private final String name;
    private final String city;
        Employee(String name, String city) { this.name = name;
        this.city = city; }
    String getCity() { return city; }
}

// ─── Would be in service/CityStatsService.java ───
class CityStatsService {
    Optional<String> mostCommonCity(List<Employee> staff) {
        Map<String, Long> counts = staff.stream()
            .filter(e -> e.getCity() != null)
            .collect(groupingBy(Employee::getCity, counting()));   // count per city
        return counts.entrySet().stream()
            .max(Map.Entry.<String, Long>comparingByValue()
                .thenComparing(Map.Entry.comparingByKey()))         // tie-break by name
            .map(Map.Entry::getKey);
    }
}
